B.baJ=new A.c(B.N,["A Igreja de Cristo n\xe3o existe para si mesma; ela \xe9 a ag\xeancia mission\xe1ria de Deus enviada a todos os povos e na\xe7\xf5es.",B.b50,"Ou a igreja \xe9 mission\xe1ria e evangel\xedstica, ou ela trai o prop\xf3sito fundamental da sua exist\xeancia na terra.","Responda ao chamado mission\xe1rio: ore, contribua ou diga 'Eis-me aqui, envia-me a mim!'."],t.R)
B.buK=new A.a9("tpl-24","O Clamor dos Povos N\xe3o Alcan\xe7ados","O Imperativo Urgente da Grande Comiss\xe3o Mission\xe1ria","Mateus 28:18-20","Tem\xe1tico",B.b0_,B.baJ)
