B.b98=new A.c(B.N,["Junto ao po\xe7o de Jac\xf3, Jesus revela \xe0 mulher samaritana o maior segredo sobre o louvor que agrada ao cora\xe7\xe3o do Alt\xedssimo.",B.b6l,"Adorar n\xe3o \xe9 cantar hinos bonitos; \xe9 viver de tal maneira que nossa vida inteira exale o aroma suave de Cristo.","Entregue a sua adora\xe7\xe3o sincera ao Senhor hoje em esp\xedrito e em verdade."],t.R)
B.bw_=new A.a9("tpl-31","Adoradores em Esp\xedrito e em Verdade","A Adora\xe7\xe3o que o Pai Procura e a Cura da Falsa Religi\xe3o","Jo\xe3o 4:23-24","Tem\xe1tico",B.aWO,B.b98)
